import numpy as np
from collections import Counter

def ngrams(ws, n):
    return Counter(tuple(ws[i:i + n]) for i in range(len(ws) - n + 1))

def bleu(ref, hyp, N=4):
    r, h = ref.lower().split(), hyp.lower().split()
    ps = []
    for n in range(1, N + 1):
        hc, rc = ngrams(h, n), ngrams(r, n)
        clipped = sum(min(c, rc[g]) for g, c in hc.items())   # 참조에 나온 횟수까지만 인정
        ps.append(clipped / max(sum(hc.values()), 1))
    bp = min(1.0, np.exp(1 - len(r) / len(h)))
    if min(ps) == 0:
        return np.round(ps, 3), round(float(bp), 4), 0.0
    return np.round(ps, 3), round(float(bp), 4), round(float(bp * np.exp(np.mean(np.log(ps)))), 4)

def rouge1_recall(ref, hyp):
    rc, hc = Counter(ref.lower().split()), Counter(hyp.lower().split())
    return round(sum(min(c, hc[w]) for w, c in rc.items()) / sum(rc.values()), 3)

print(bleu("the cat sat on the mat", "the cat sat on mat"))
print(bleu("the cat sat on the mat", "the the the the the the", N=1))
ref = "a plush teddy bear can comfort a child during bedtime"
for hyp in ["soft stuffed bears often help kids feel safe as they fall asleep",
            "many youngsters rest more easily at night when they cuddle a gentle toy companion",
            "a plush teddy bear can comfort a dog during bedtime"]:
    print(bleu(ref, hyp)[2], rouge1_recall(ref, hyp), "|", hyp)

from math import comb

def pass_at_k(n, c, k):        # k 번 중 하나라도 성공(6강)
    return 1.0 if n - c < k else 1 - comb(n - c, k) / comb(n, k)

def pass_hat_k(n, c, k):       # k 번 모두 성공(τ-bench) — n 번 중 성공 c 번에서 k 개를 고른다
    return comb(c, k) / comb(n, k)

n, c = 8, 6
for k in [1, 2, 4, 8]:
    print(f"k={k}: pass@k={pass_at_k(n, c, k):.3f}  pass^k={pass_hat_k(n, c, k):.3f}")
# 과제마다 성공 확률이 다른 두 에이전트 — pass^1 은 같아도 pass^k 는 갈린다
A = [0.75] * 4                 # 네 과제 모두 75%
B = [1.0, 1.0, 1.0, 0.0]       # 세 과제는 언제나, 한 과제는 절대
for k in [1, 4, 8]:
    print(k, round(sum(p ** k for p in A) / 4, 3), round(sum(p ** k for p in B) / 4, 3))
